package org.telegram.spectra;

import android.content.Context;
import android.util.TypedValue;

/**
 * Bridge between SpectraConfig and the generated SpectraPalette (theme overrides).
 * The palette table itself is generated by scripts/gen_spectra_theme.py with every
 * key validated against Theme.java, and applied at runtime via reflection.
 */
public final class SpectraThemeUtils {

    private SpectraThemeUtils() {}

    public static void apply() {
        try {
            SpectraPalette.apply();
        } catch (Throwable ignore) {}
    }

    public static int systemAccent() {
        try {
            Context ctx = org.telegram.messenger.ApplicationLoader.applicationContext;
            TypedValue tv = new TypedValue();
            ctx.getTheme().resolveAttribute(android.R.attr.colorAccent, tv, true);
            return tv.data;
        } catch (Throwable t) {
            return 0xFF2CE876;
        }
    }

    public static void onConfigChanged(String key) {
        apply();
        SpectraGlassPanel.refreshAll();
        try {
            org.telegram.messenger.NotificationCenter.getGlobalInstance()
                    .postNotificationName(org.telegram.messenger.NotificationCenter.didSetNewTheme, Boolean.FALSE, true);
        } catch (Throwable ignore) {}
    }
}
